//! 📥️ Test-only source admission drives each real stage from the caller's existing finite wallet.
pub use semio_framework_value_control_contract::*;
pub use semio_framework_value_native_decoding::{native_decoding,native_decoding::NativeDecodeControl,native_decoding::OriginalReceivingPrimary};
pub use semio_framework_value_retained_clone::retained_clone;
pub use semio_framework_value_retirement::retirement;
use crate::{retained_clone::RetainedCloneSource,retirement::RetireOwned};
pub fn capture<T:RetireOwned+Sync,W>(value:T,wallet:&mut W,loan:impl Fn(&W)->RetainedCloneGrant,mut post:impl FnMut(&mut W,RetainedCloneProgress,u64,(usize,usize),RetainedCloneGrant))->RetainedCloneSource<T>{
 let mut owner=RetainedCloneSource::admission_owned(value,());for _ in 0..10000{if owner.phase()=="ready"{break}let g=loan(wallet);let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||owner.advance(g));assert!(turn.work<=1);let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));post(wallet,p,turn.work,heap,g);turn.result.unwrap();}assert_eq!(owner.phase(),"ready","source fixture failed at its actual demand {:?}",owner.next_demand());let mut output=None;let g=loan(wallet);let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||owner.take_output(&mut output,g));assert!(turn.work<=1);let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));post(wallet,p,turn.work,heap,g);turn.result.unwrap();assert!(owner.terminal_is_empty());output.expect("paid source output remains in its actual caller slot")
}

struct ConstructionLoan{current:RetainedCloneGrant,issued:bool,accepted:bool}
impl crate::native_decoding::NativeDecodeConstructionRecipient for ConstructionLoan{fn grant(&mut self,d:crate::RetirementDemand)->Result<RetainedCloneGrant,crate::ValueError>{assert!(!self.issued);assert!(crate::retained_clone::retained_clone_grant_admits(self.current,d));self.issued=true;Ok(self.current)}fn accept(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),crate::ValueError>{assert!(!self.accepted);assert!(p.fits(g));assert!(p.fits(self.current));assert!(g.maximum_items<=self.current.maximum_items&&g.maximum_copy_bytes<=self.current.maximum_copy_bytes&&g.maximum_capacity_bytes<=self.current.maximum_capacity_bytes&&g.maximum_release_bytes<=self.current.maximum_release_bytes&&g.maximum_depth<=self.current.maximum_depth);self.accepted=true;Ok(())}}
pub struct WorkLoan<'a>{remaining:&'a u64,maximum:u64}
impl<'a> WorkLoan<'a>{pub fn new(remaining:&'a u64,maximum:u64)->Self{Self{remaining,maximum}}}
impl crate::native_decoding::NativeDecodeWorkRecipient for WorkLoan<'_>{fn admits(&mut self,observed:u64,additional:u64)->Result<bool,crate::ValueError>{Ok(observed.checked_add(additional).is_some_and(|n|n<=(*self.remaining).min(self.maximum)))}}
pub fn receive<T,E:From<crate::ValueError>>(control:&mut crate::NativeDecodeControl<'_>,g:RetainedCloneGrant,mut work_loan:WorkLoan<'_>,apply:impl FnOnce(&mut crate::NativeDecodeControl<'_>)->crate::RetainedWorkOutcome<T,E>)->crate::RetainedWorkOutcome<T,E>{let mut loan=ConstructionLoan{current:g,issued:false,accepted:false};let mut work=0;let result=control.with_work_recipient(&mut work_loan,|control|control.with_construction_recipient(&mut loan,|control|{let turn=apply(control);work=turn.work;turn.result}));crate::RetainedWorkOutcome{result,work}}


pub struct Wallet{left:RetainedCloneGrant,work:u64}
impl Wallet{
 pub fn work_loan(&self,maximum:u64)->WorkLoan<'_>{WorkLoan::new(&self.work,maximum)}
 pub fn from_profile(profile:&serde_json::Value)->Self{Self{left:RetainedCloneGrant{maximum_items:profile["items"].as_u64().unwrap().try_into().unwrap(),maximum_copy_bytes:profile["copyBytes"].as_u64().unwrap().try_into().unwrap(),maximum_capacity_bytes:profile["capacityBytes"].as_u64().unwrap().try_into().unwrap(),maximum_release_bytes:profile["releaseBytes"].as_u64().unwrap().try_into().unwrap(),maximum_depth:profile["depth"].as_u64().unwrap().try_into().unwrap()},work:profile["fuel"].as_u64().unwrap()}}
 pub fn loan(&self,items:usize,copy:usize)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:if self.work==0{0}else{self.left.maximum_items.min(items)},maximum_copy_bytes:self.left.maximum_copy_bytes.min(copy),..self.left}}
 pub fn post(&mut self,p:RetainedCloneProgress,work:u64,g:RetainedCloneGrant,heap:(usize,usize)){assert!(p.fits(g));assert!(p.fits(self.left));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));self.left.maximum_items=self.left.maximum_items.checked_sub(p.copied_items).unwrap();self.left.maximum_copy_bytes=self.left.maximum_copy_bytes.checked_sub(p.copied_bytes).unwrap();self.left.maximum_capacity_bytes=self.left.maximum_capacity_bytes.checked_sub(p.retained_capacity_bytes).unwrap();self.left.maximum_release_bytes=self.left.maximum_release_bytes.checked_sub(p.released_bytes).unwrap();self.work=self.work.checked_sub(work).expect("native fixture depleted its explicit CPU stock");}
}

pub fn post_step<E>(wallet:&mut Wallet,turn:crate::RetainedWorkOutcome<crate::RetainedCloneStep,E>,grant:RetainedCloneGrant,heap:(usize,usize),receipt:impl FnOnce(&E)->RetainedCloneProgress)->Result<crate::RetainedCloneStep,E>{let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(receipt);assert!(turn.work<=1);wallet.post(p,turn.work,grant,heap);turn.result}
pub fn denials(g:RetainedCloneGrant,d:crate::RetirementDemand)->impl Iterator<Item=RetainedCloneGrant>{[(true,RetainedCloneGrant{maximum_items:0,..g}),(d.copy_bytes>0,RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g}),(d.capacity_bytes>0,RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g}),(d.release_bytes>0,RetainedCloneGrant{maximum_release_bytes:d.release_bytes.saturating_sub(1),..g}),(d.depth>0,RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..g})].into_iter().filter_map(|(yes,g)|yes.then_some(g))}
pub fn close_owned<T:RetireOwned>(value:T,wallet:&mut Wallet,body:usize,limit:usize){let(mut owner,h)=semio_framework_value_testing_allocator::observe_retirement_allocations(||crate::retirement::controlled::ControlledRetirement::new(value).unwrap_or_else(|_|panic!("native fixture supports paid original closure")));assert_eq!(h,(0,0));for _ in 0..limit{if owner.terminal_is_empty(){return}let d=owner.next_demand(body).unwrap();assert!(d.copy_bytes<=body);let g=wallet.loan(1,body);let(result,h)=semio_framework_value_testing_allocator::observe_retirement_allocations(||owner.step(g));let work=owner.last_turn_work();post_step(wallet,crate::RetainedWorkOutcome{result,work},g,h,crate::ValueError::retained_progress).unwrap();}panic!("native fixture did not close in its original turn bound")}
